S = "Hakeem Force Academy"
QS = [
(S, "The Battle of Furqan is the name of which ghazwa?", ["Ghazwa Uhud", "Ghazwa Badr", "Ghazwa Khandaq", "Ghazwa Hunain"], 1,
 "The Quran calls the day of Badr Yawm al-Furqan, the Day of Distinction between truth and falsehood. So the Battle of Furqan is the Battle of Badr.", "Badr was fought in 2 AH (624 CE) and about 313 Muslims faced roughly 1000 Makkan soldiers.", 1),
(S, "The census of Pakistan is conducted by which organization?", ["State Bank of Pakistan", "Pakistan Bureau of Statistics", "Election Commission of Pakistan", "NADRA"], 1,
 "Population and housing censuses in Pakistan are carried out by the Pakistan Bureau of Statistics. NADRA and the Election Commission only use the data or registers.", "The 2017 and the digital 2023 censuses were both conducted by the Pakistan Bureau of Statistics.", 1),
(S, "The Dorah Pass connects Pakistan with which country?", ["China", "Iran", "Afghanistan", "Tajikistan"], 2,
 "The Dorah Pass lies on the Chitral border and leads from Pakistan into Afghanistan (Badakhshan).", "Chitral district of Khyber Pakhtunkhwa is the Pakistani side of the Dorah Pass.", 1),
(S, "The first 5 verses revealed to Prophet Muhammad (PBUH) belong to which surah?", ["Surah Al-Muddaththir", "Surah Al-Muzzammil", "Surah Al-Alaq", "Surah Al-Fatiha"], 2,
 "The first five ayats revealed in the Cave of Hira begin with Iqra bismi rabbika and are from Surah Al-Alaq.", "Surah Al-Alaq is also called Surah Iqra.", 2),
(S, "The Hindukush range connects Pakistan with which country?", ["Iran", "Afghanistan", "India", "China"], 1,
 "The Hindukush mountains run along the north-western border of Pakistan and extend into Afghanistan.", "Tirich Mir (7708 m) in the Hindukush is the highest peak of the range in Pakistan.", 1),
(S, "The Holy Prophet (PBUH) appointed Hazrat Maaz bin Jabal (RA) as governor of which place?", ["Yemen", "Bahrain", "Oman", "Syria"], 0,
 "The Prophet (PBUH) sent Hazrat Maaz bin Jabal to Yemen as governor and teacher of the people.", "Hazrat Maaz bin Jabal was known as the most knowledgeable of the Companions in halal and haram.", 1),
(S, "The Indus Waters Treaty of 1960 was made with the mediation of which organization?", ["United Nations", "World Bank", "IMF", "Commonwealth"], 1,
 "The treaty between Pakistan and India was brokered by the World Bank and signed in Karachi in September 1960.", "India announced in April 2025 that it was holding the treaty in abeyance, and Pakistan rejects this move.", 1),
(S, "Under the Indus Waters Treaty, Pakistan has rights over which rivers?", ["Ravi, Beas and Sutlej", "Indus, Jhelum and Chenab", "Ravi, Chenab and Sutlej", "Beas, Jhelum and Indus"], 1,
 "The three western rivers Indus, Jhelum and Chenab were allotted to Pakistan. The eastern rivers Ravi, Beas and Sutlej were given to India.", "Pakistan and India agreed on the treaty after the Indus basin water dispute that followed Partition.", 1),
(S, "The Khyber Pass connects Pakistan with which country?", ["Afghanistan", "Iran", "China", "India"], 0,
 "The Khyber Pass links Peshawar in Pakistan with Jalalabad and Kabul in Afghanistan.", "The Khyber Pass is about 53 km long and has been an invasion and trade route for centuries.", 1),
(S, "The nation of which prophet was destroyed by a rain of stones?", ["Hazrat Nooh (AS)", "Hazrat Saleh (AS)", "Hazrat Loot (AS)", "Hazrat Hood (AS)"], 2,
 "The Quran says the sinful people of Hazrat Loot (AS) were destroyed by a shower of baked clay stones.", "The nation of Hazrat Nooh (AS) was destroyed by flood and the people of Aad by a violent wind.", 1),
(S, "The OIC is an organization of which countries?", ["Oil-producing countries", "Muslim countries", "Asian countries", "Non-aligned countries"], 1,
 "The Organisation of Islamic Cooperation is the collective voice of Muslim countries of the world.", "The OIC was founded in 1969 in Rabat and its headquarters are in Jeddah, Saudi Arabia.", 2),
(S, "The Panama Canal connects the Pacific Ocean with which ocean?", ["Indian Ocean", "Arctic Ocean", "Atlantic Ocean", "Southern Ocean"], 2,
 "The canal cuts across Panama and joins the Pacific Ocean with the Atlantic Ocean through the Caribbean Sea.", "The Panama Canal was opened in 1914 while the Suez Canal links the Mediterranean with the Red Sea.", 1),
(S, "Under the Constitution of Pakistan, the President is bound to act on the advice of whom?", ["Chief Justice", "Prime Minister", "Chief of Army Staff", "Speaker of the National Assembly"], 1,
 "Article 48 of the Constitution requires the President to act on the advice of the Prime Minister (or the Cabinet).", "Pakistan has a parliamentary system in which the Prime Minister is the real executive head.", 1),
(S, "The river Amazon is ___ largest river of South America.", ["a", "an", "the", "from"], 2,
 "A superlative such as largest takes the definite article the.", "The Amazon is the largest river in the world by volume of water.", 1),
(S, "The rouble is the currency of which country?", ["Poland", "Ukraine", "Russia", "Kazakhstan"], 2,
 "The Russian rouble is the national currency of Russia.", "Belarus also uses a currency called the Belarusian ruble.", 1),
(S, "The Secretary-General of the United Nations, Antonio Guterres, belongs to which country?", ["Spain", "Portugal", "Brazil", "Italy"], 1,
 "Antonio Guterres, the ninth UN Secretary-General, is a former Prime Minister of Portugal.", "His term ends on 31 December 2026 and the selection of his successor is under way; before him Ban Ki-moon of South Korea held the post.", 1),
(S, "The Shimla Agreement of 1972 was signed between Zulfikar Ali Bhutto and whom?", ["Lal Bahadur Shastri", "Indira Gandhi", "Jawaharlal Nehru", "Morarji Desai"], 1,
 "After the 1971 war, Bhutto and the Indian Prime Minister Indira Gandhi signed the agreement at Shimla on 2 July 1972.", "The agreement turned the cease-fire line in Kashmir into the Line of Control.", 1),
(S, "The Silk Road connects Pakistan with which country?", ["Iran", "Afghanistan", "China", "Turkey"], 2,
 "The Karakoram Highway follows part of the ancient Silk Road and links Pakistan to China through the Khunjerab Pass.", "The China-Pakistan Economic Corridor is a modern project built along this old route.", 2),
(S, "The T.A.P.I gas pipeline starts from which country?", ["Afghanistan", "Turkmenistan", "Pakistan", "India"], 1,
 "TAPI stands for Turkmenistan, Afghanistan, Pakistan, India, and the gas comes from Turkmenistan (Galkynysh field).", "The pipeline is planned to carry about 33 billion cubic metres of gas a year.", 1),
(S, "Choose the correct reported speech: The teacher asked, Who is speaking English?", ["The teacher wanted to know who is speaking English.", "The teacher wanted to know who was speaking English.", "The teacher wanted to know who has spoken English.", "The teacher wanted to know who speaks English was."], 1,
 "In reported speech a present continuous question changes to past continuous, so is speaking becomes was speaking, and the question order becomes a statement.", "The reporting verb asked is usually changed to wanted to know or enquired.", 1),
(S, "The Wakhan Corridor separates Pakistan from which country?", ["China", "Iran", "Tajikistan", "India"], 2,
 "The narrow Wakhan Corridor of Afghanistan lies between Pakistan on the south and Tajikistan on the north.", "The corridor also touches China at its eastern end.", 1),
(S, "The word Everyone is what part of speech?", ["Noun", "Adjective", "Pronoun", "Adverb"], 2,
 "Everyone stands in place of a noun (all people), so it is an indefinite pronoun.", "Other indefinite pronouns are someone, anybody and nobody.", 1),
(S, "Thimphu is the capital of which country?", ["Nepal", "Bhutan", "Sri Lanka", "Myanmar"], 1,
 "Thimphu is the capital and largest city of Bhutan.", "Bhutan is a Himalayan kingdom between China and India.", 1),
(S, "Through which of these countries does the Tropic of Cancer not pass?", ["India", "Bangladesh", "Egypt", "Pakistan"], 3,
 "The Tropic of Cancer (23.5 degrees north) crosses India, Bangladesh and Egypt, but Pakistan lies north of it.", "It also passes through Mexico, Saudi Arabia, Libya and southern China.", 1),
(S, "Through which of these countries does the Tropic of Capricorn not pass?", ["Australia", "Brazil", "India", "South Africa"], 2,
 "The Tropic of Capricorn (23.5 degrees south) lies in the southern hemisphere, and India is entirely in the northern hemisphere.", "It also crosses Chile, Argentina, Namibia, Botswana and Madagascar.", 1),
(S, "To where did the Muslims first migrate?", ["Madina", "Abyssinia", "Taif", "Yemen"], 1,
 "In 615 CE (5th year of the Prophethood) a group of Muslims migrated to Abyssinia to escape persecution in Makkah.", "The king of Abyssinia, Negus (Najashi), gave them protection.", 1),
]
